<script setup lang="ts">
import { Mail } from '@lucide/vue'
import { Icon } from '@iconify/vue'

interface GithubProfile { name: string; login: string; bio: string | null; avatar_url: string; html_url: string; location: string | null; public_repos: number; followers: number }
interface GithubRepo { id: number; name: string; description: string | null; html_url: string; language: string | null; topics?: string[]; stargazers_count: number; forks_count: number; updated_at: string; fork: boolean }
interface Technology { name: string; icon: string }

const username = 'AyserNii'
const profile = ref<GithubProfile | null>(null)
const repositories = ref<GithubRepo[]>([])
const isLoading = ref(true)
const hasError = ref(false)
const activeFilter = ref('All')
const selectedRepo = ref<GithubRepo | null>(null)
const isContactOpen = ref(false)
const isMenuOpen = ref(false)
const menuTouchStartX = ref(0)
const scrollProgress = ref(0)
const isDark = ref(false)
const language = ref<'id' | 'en'>('id')
const isThemeAnimating = ref(false)
const nextThemeClass = computed(() => isDark.value ? 'spread-light' : 'spread-dark')
const copy = {
  id: { available: 'Terbuka untuk petualangan baru', heroTitle: 'Membangun hal digital<br><em>dengan niat.</em>', heroDescription: 'Developer yang suka mengubah ide penuh perhatian menjadi pengalaman yang cepat, berguna, dan indah dengan caranya sendiri.', explore: 'Lihat karya', profile: 'Profil GitHub', work: 'Karya', about: 'Tentang', hobbiesNav: 'Hobi', selectedWork: 'Karya pilihan', workTitle: 'Hal yang pernah saya buat.', workIntro: 'Koleksi eksperimen, tools, dan ide yang terus diperbarui dari GitHub.', aboutLabel: 'Sedikit tentang saya', aboutTitle: 'Selalu ingin tahu.<br><em>Dikerjakan</em> dengan niat.', beyond: 'Di luar kode', beyondTitle: 'Apa yang membuat saya<br><em>penasaran.</em>', beyondIntro: 'Hal-hal kecil yang mengisi ulang energi dan sering menyelip ke dalam ide project.', email: 'Email', whatsapp: 'WhatsApp', instagram: 'Instagram', chatWhatsapp: 'Chat langsung melalui WhatsApp', openConversation: 'Mulai percakapan', contactIntro: 'Pilih cara yang paling nyaman untuk ngobrol, berkolaborasi, atau sekadar menyapa.', letsTalk: 'Mari ngobrol', repository: 'Detail repository', viewRepository: 'Lihat repository', close: 'Tutup', backTop: 'Kembali ke atas', repositories: 'repository', followers: 'pengikut', loading: 'Mengambil karya terbaru', tryAgain: 'Coba lagi', githubPause: 'GitHub sedang beristirahat sebentar.', noRepos: 'Belum ada repository di kategori ini.', footer: '© 2026 AyserNii' },
  en: { available: 'Available for a new adventure', heroTitle: 'Building digital<br><em>things</em> with intent.', heroDescription: 'A developer who enjoys turning thoughtful ideas into fast, useful, and quietly beautiful experiences.', explore: 'Explore my work', profile: 'GitHub profile', work: 'Work', about: 'About', hobbiesNav: 'Hobbies', selectedWork: 'Selected work', workTitle: "Things I've made.", workIntro: 'A live collection of experiments, tools, and ideas from GitHub.', aboutLabel: 'A little about me', aboutTitle: 'Curious by nature.<br><em>Intentional</em> by craft.', beyond: 'Beyond the code', beyondTitle: 'What keeps me<br><em>curious.</em>', beyondIntro: 'The small things that refill the creative tank and sneak into my project ideas.', email: 'Email', whatsapp: 'WhatsApp', instagram: 'Instagram', chatWhatsapp: 'Chat directly via WhatsApp', openConversation: 'Open a conversation', contactIntro: 'Choose the easiest way to talk, collaborate, or simply say hello.', letsTalk: "Let's talk", repository: 'Repository detail', viewRepository: 'View repository', close: 'Close', backTop: 'Back to top', repositories: 'repositories', followers: 'followers', loading: 'Gathering the latest work', tryAgain: 'Try again', githubPause: 'GitHub is taking a little pause.', noRepos: 'No repositories in this category yet.', footer: '© 2026 AyserNii' },
}
const extraCopy = {
  id: { basedIn: 'Berdomisili di', internet: 'internet', scroll: 'Gulir untuk melihat', role: 'developer / kreator', repoFallback: 'Sudut kecil di internet yang dibuat dengan penuh perhatian.', modalFallback: 'Proyek yang dibuat dengan rasa penasaran dan perhatian.', aboutParagraphs: ['Saya adalah pengembang web dengan fokus utama pada frontend. Saya senang mengubah desain menjadi antarmuka yang bersih, responsif, dan nyaman digunakan.', 'Saya juga terbiasa mengerjakan sisi backend menggunakan Laravel dan Golang, termasuk membangun REST API dan mengelola database MySQL maupun PostgreSQL. Dalam setiap proyek, saya berusaha menjaga clean code, performa, dan pengalaman pengguna tetap seimbang.', 'Saya terbuka terhadap masukan, nyaman bekerja dalam tim, dan selalu punya rasa penasaran untuk mempelajari teknologi baru.'] },
  en: { basedIn: 'Based in', internet: 'the internet', scroll: 'Scroll to discover', role: 'developer / creator', repoFallback: 'A little corner of the internet, built with care.', modalFallback: 'A project built with curiosity and care.', aboutParagraphs: ['I am a Web Developer focused on frontend development. I enjoy turning designs into interfaces that are clean, responsive, and comfortable to use.', 'I also work across the backend with Laravel and Golang, including REST APIs and MySQL or PostgreSQL databases. In every project, I try to keep clean code, performance, and user experience in balance.', 'I am open to feedback, comfortable working in teams, and always curious to keep learning new technologies.'] },
}
const t = computed(() => ({ ...copy[language.value], ...extraCopy[language.value] }))
const hobbies = computed(() => language.value === 'id' ? [
  { title: 'Nonton anime', text: 'Buat recharge, menikmati cerita, dan kadang menemukan ide visual baru.', image: '/images/anime-merasa.jpg' },
  { title: 'Bikin ide project', text: 'Mengubah rasa penasaran dan masalah kecil menjadi sesuatu yang bisa dipakai.', image: '/images/anime-laugh.jpg' },
  { title: 'Baca novel', text: 'Menyelami sudut pandang baru yang sering ikut membentuk cara saya bercerita.', image: '/images/anime-nope.jpg' },
  { title: 'Main game', text: 'Menikmati eksplorasi, tantangan, dan interaksi yang terasa natural.', image: '/images/anime-think.jpg' },
] : [
  { title: 'Watching anime', text: 'A way to recharge, enjoy stories, and occasionally find new visual ideas.', image: '/images/anime-merasa.jpg' },
  { title: 'Building project ideas', text: 'Turning curiosity and small problems into something people can use.', image: '/images/anime-laugh.jpg' },
  { title: 'Reading novels', text: 'Exploring new perspectives that often shape the way I tell stories.', image: '/images/anime-nope.jpg' },
  { title: 'Playing games', text: 'Enjoying exploration, challenges, and interactions that feel natural.', image: '/images/anime-think.jpg' },
])
const filters = computed(() => ['All', ...new Set(repositories.value.map((repo) => repo.language).filter(Boolean) as string[])])
const filteredRepositories = computed(() => activeFilter.value === 'All' ? repositories.value : repositories.value.filter((repo) => repo.language === activeFilter.value))
const technologyIcons: Record<string, string> = {
  javascript: 'logos:javascript', typescript: 'logos:typescript', vue: 'logos:vue', nuxt: 'logos:nuxt-icon',
  react: 'logos:react', nextjs: 'logos:nextjs-icon', node: 'logos:nodejs-icon', nodejs: 'logos:nodejs-icon',
  php: 'logos:php', laravel: 'logos:laravel', go: 'logos:go', golang: 'logos:go', python: 'logos:python',
  mysql: 'logos:mysql', postgresql: 'logos:postgresql', tailwind: 'logos:tailwindcss-icon', tailwindcss: 'logos:tailwindcss-icon',
}
const technologies = computed<Technology[]>(() => {
  const names = repositories.value.flatMap((repo) => [repo.language, ...(repo.topics || [])]).filter(Boolean) as string[]
  return [...new Set(names.map((name) => name.toLowerCase()))]
    .filter((name) => technologyIcons[name])
    .map((name) => ({ name: name === 'nodejs' ? 'Node.js' : name.charAt(0).toUpperCase() + name.slice(1), icon: technologyIcons[name] }))
})
const formatNumber = (value: number) => new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 1 }).format(value)
const formatDate = (date: string) => new Intl.DateTimeFormat('en', { month: 'short', year: 'numeric' }).format(new Date(date))

async function loadGithubData() {
  isLoading.value = true
  hasError.value = false
  try {
    const headers = { Accept: 'application/vnd.github+json' }
    const [profileData, repoData] = await Promise.all([
      $fetch<GithubProfile>(`https://api.github.com/users/${username}`, { headers }),
      $fetch<GithubRepo[]>(`https://api.github.com/users/${username}/repos?per_page=100&sort=updated`, { headers }),
    ])
    profile.value = profileData
    repositories.value = repoData.filter((repo) => !repo.fork)
  } catch { hasError.value = true } finally { isLoading.value = false }
}
function toggleTheme() {
  if (isThemeAnimating.value) return
  isThemeAnimating.value = true
  window.setTimeout(() => {
    isDark.value = !isDark.value
    localStorage.setItem('aysernii-theme', isDark.value ? 'dark' : 'light')
    isThemeAnimating.value = false
  }, 650)
}
function toggleLanguage() {
  language.value = language.value === 'id' ? 'en' : 'id'
  localStorage.setItem('aysernii-language', language.value)
}
function closeMenu() {
  isMenuOpen.value = false
}
function handleMenuTouchStart(event: TouchEvent) {
  menuTouchStartX.value = event.changedTouches[0]?.clientX || 0
}
function handleMenuTouchEnd(event: TouchEvent) {
  const touchEndX = event.changedTouches[0]?.clientX || 0
  if (touchEndX - menuTouchStartX.value > 70) closeMenu()
}
function openContactFromMenu() {
  closeMenu()
  isContactOpen.value = true
}
function updateScrollProgress() {
  const scrollableHeight = document.documentElement.scrollHeight - window.innerHeight
  scrollProgress.value = scrollableHeight > 0 ? Math.min(100, Math.round((window.scrollY / scrollableHeight) * 100)) : 0
}
function scrollToTop() {
  window.scrollTo({ top: 0, behavior: 'smooth' })
}
onMounted(() => {
  isDark.value = localStorage.getItem('aysernii-theme') === 'dark'
  language.value = localStorage.getItem('aysernii-language') === 'en' ? 'en' : 'id'
  window.addEventListener('scroll', updateScrollProgress, { passive: true })
  updateScrollProgress()
  loadGithubData()
})
onBeforeUnmount(() => window.removeEventListener('scroll', updateScrollProgress))
</script>

<template>
  <div class="site-shell" :class="{ 'theme-dark': isDark }">
    <div v-if="isThemeAnimating" class="theme-spread" :class="nextThemeClass" aria-hidden="true" />
    <Transition name="loading"><div v-if="isLoading" class="loading-screen" role="status" aria-live="polite"><div class="loading-brand"><span class="loading-orbit" /><img src="/images/logo.png" alt="AyserNii logo"><span class="loading-brand-name">AyserNii</span></div><p>{{ t.loading }}<span class="loading-dots">...</span></p><div class="loading-line"><span /></div></div></Transition>
    <header class="topbar"><a class="brand" href="#top"><span class="brand-logo"><img src="/images/logo.png" alt="AyserNii logo"></span><span>AyserNii</span></a><nav class="nav-links"><a href="#work">{{ t.work }}</a><a href="#about">{{ t.about }}</a><a href="#hobbies">{{ t.hobbiesNav }}</a></nav><div class="header-actions"><button class="language-toggle" :aria-label="language === 'id' ? 'Switch to English' : 'Ganti ke Bahasa Indonesia'" @click="toggleLanguage">{{ language.toUpperCase() }}</button><button class="theme-toggle" :aria-label="isDark ? 'Switch to light mode' : 'Switch to dark mode'" :title="isDark ? 'Switch to light mode' : 'Switch to dark mode'" @click="toggleTheme"><span>{{ isDark ? '☀' : '☾' }}</span></button><button class="contact-link contact-button" @click="isContactOpen = true">{{ t.letsTalk }} <span>↗</span></button><button class="menu-toggle" :class="{ open: isMenuOpen }" :aria-expanded="isMenuOpen" :aria-label="isMenuOpen ? t.close : 'Open menu'" @click="isMenuOpen = !isMenuOpen"><span /><span /></button></div></header>
    <Transition name="drawer"><div v-if="isMenuOpen" class="mobile-menu" @click.self="closeMenu"><nav class="mobile-menu-panel" @touchstart="handleMenuTouchStart" @touchend="handleMenuTouchEnd"><div class="mobile-menu-head"><span>Menu</span><button class="menu-close" :aria-label="t.close" @click="closeMenu">×</button></div><a href="#work" @click="closeMenu">{{ t.work }} <span>↘</span></a><a href="#about" @click="closeMenu">{{ t.about }} <span>↘</span></a><a href="#hobbies" @click="closeMenu">{{ t.hobbiesNav }} <span>↘</span></a><button class="mobile-menu-contact" @click="openContactFromMenu">{{ t.letsTalk }} <span>↗</span></button></nav></div></Transition>
    <main id="top">
      <section class="hero section-wrap"><div class="hero-copy reveal-up"><p class="eyebrow"><span class="status-dot" /> {{ t.available }}</p><h1 v-html="t.heroTitle" /><p class="hero-description">{{ t.heroDescription }}</p><div class="hero-actions"><a class="button button-dark" href="#work">{{ t.explore }} <span>↓</span></a><a class="text-link" href="https://github.com/AyserNii" target="_blank" rel="noreferrer">{{ t.profile }} <span>↗</span></a></div></div><div class="hero-portrait reveal-up delay-one"><img :src="'/images/resya3.jpg'" alt="Resya wearing a formal suit"><span>Resya Anggara<br><strong>{{ t.role }}</strong></span></div><div class="hero-note reveal-up delay-one"><span class="note-line" /><p>{{ t.basedIn }}<br><strong>{{ profile?.location || t.internet }}</strong></p></div><div class="scroll-cue">{{ t.scroll }} <span>↓</span></div></section>
      <section id="work" class="work-section section-wrap"><div v-if="technologies.length" class="technology-marquee reveal-up" aria-label="Technologies used"><div class="technology-track"><div v-for="copyIndex in 4" :key="copyIndex" class="technology-group" :aria-hidden="copyIndex > 1"><span v-for="technology in technologies" :key="`${copyIndex}-${technology.name}`" class="technology-item" :title="copyIndex === 1 ? technology.name : undefined"><Icon :icon="technology.icon" /><span>{{ technology.name }}</span></span></div></div></div><div class="section-heading reveal-up"><div><p class="eyebrow">{{ t.selectedWork }}</p><h2>{{ t.workTitle }}</h2></div><p class="section-intro">{{ t.workIntro }}</p></div>
        <div v-if="isLoading" class="repo-grid loading-grid"><div v-for="index in 6" :key="index" class="repo-card skeleton-card"><div class="skeleton skeleton-tag" /><div class="skeleton skeleton-title" /><div class="skeleton skeleton-copy" /><div class="skeleton skeleton-foot" /></div></div>
        <div v-else-if="hasError" class="empty-state"><strong>{{ t.githubPause }}</strong><button class="text-link" @click="loadGithubData">{{ t.tryAgain }} ↗</button></div>
        <template v-else><div class="filter-row"><button v-for="filter in filters" :key="filter" class="filter-button" :class="{ active: activeFilter === filter }" @click="activeFilter = filter">{{ filter }}</button></div><div class="repo-grid"><article v-for="(repo, index) in filteredRepositories" :key="repo.id" class="repo-card reveal-up" :class="`delay-${Math.min(index + 1, 4)}`" @click="selectedRepo = repo"><div class="card-top"><span class="repo-index">0{{ index + 1 }}</span><span class="arrow-icon">↗</span></div><h3>{{ repo.name.replaceAll('-', ' ') }}</h3><p>{{ repo.description || t.repoFallback }}</p><div class="card-footer"><span class="language"><i :style="{ backgroundColor: repo.language === 'TypeScript' ? '#3178c6' : repo.language === 'JavaScript' ? '#e8c12f' : '#62a67a' }" />{{ repo.language || 'Code' }}</span><span>{{ formatDate(repo.updated_at) }}</span></div></article></div><p v-if="filteredRepositories.length === 0" class="empty-state">{{ t.noRepos }}</p></template>
      </section>
      <section id="about" class="about-section section-wrap"><div class="about-heading reveal-up"><p class="eyebrow">{{ t.aboutLabel }}</p><h2 v-html="t.aboutTitle" /></div><div class="about-content reveal-up delay-one"><div class="profile-block"><img :src="profile?.avatar_url || '/images/resya2.jpg'" alt="AyserNii GitHub profile"><div><strong>{{ profile?.name || 'Resya Anggara' }}</strong><span>@{{ profile?.login || username }}</span></div></div><div class="about-copy"><p v-for="paragraph in t.aboutParagraphs" :key="paragraph">{{ paragraph }}</p></div><div class="stats"><div><strong>{{ profile ? formatNumber(profile.public_repos) : '—' }}</strong><span>{{ t.repositories }}</span></div><div><strong>{{ profile ? formatNumber(profile.followers) : '—' }}</strong><span>{{ t.followers }}</span></div></div><img class="about-photo" src="/images/resya2.jpg" alt="Resya outdoors"></div></section>
      <section id="hobbies" class="hobbies-section section-wrap"><div class="section-heading reveal-up"><div><p class="eyebrow">{{ t.beyond }}</p><h2 v-html="t.beyondTitle" /><p class="section-intro">{{ t.beyondIntro }}</p></div></div><div class="hobby-scatter"><article v-for="(hobby, index) in hobbies" :key="hobby.title" class="hobby-note reveal-up" :class="`delay-${Math.min(index + 1, 4)}`"><span class="hobby-number">0{{ index + 1 }}</span><div class="hobby-note-copy"><h3>{{ hobby.title }}</h3><p>{{ hobby.text }}</p></div><img :src="hobby.image" :alt="hobby.title"></article></div></section>
    </main>
    <footer class="footer section-wrap"><span>{{ t.footer }}</span><div class="social-links"><a href="https://www.instagram.com/ayser_nii/" target="_blank" rel="noreferrer" aria-label="Instagram"><Icon icon="simple-icons:instagram" /> <span>Instagram</span></a><a href="https://github.com/AyserNii" target="_blank" rel="noreferrer" aria-label="GitHub"><Icon icon="simple-icons:github" /> <span>GitHub</span></a><a href="https://www.linkedin.com/in/resya-anggara-912098394?utm_source=share_via&utm_content=profile&utm_medium=member_android" target="_blank" rel="noreferrer" aria-label="LinkedIn"><Icon icon="simple-icons:linkedin" /> <span>LinkedIn</span></a></div></footer>
    <button v-if="scrollProgress > 3" class="scroll-top-button" :aria-label="t.backTop" :title="`${scrollProgress}%`" @click="scrollToTop"><svg viewBox="0 0 44 44" aria-hidden="true"><circle class="scroll-track" cx="22" cy="22" r="19" /><circle class="scroll-progress" cx="22" cy="22" r="19" :style="{ strokeDashoffset: 119.4 - (119.4 * scrollProgress) / 100 }" /></svg><span>↑</span></button>
    <Transition name="modal"><div v-if="selectedRepo || isContactOpen" class="modal-backdrop" @click.self="selectedRepo = null; isContactOpen = false"><div class="repo-modal"><button class="close-button" :aria-label="t.close" @click="selectedRepo = null; isContactOpen = false">×</button><template v-if="selectedRepo"><span class="eyebrow">{{ t.repository }}</span><h2>{{ selectedRepo.name.replaceAll('-', ' ') }}</h2><p>{{ selectedRepo.description || t.modalFallback }}</p><div class="modal-meta"><span>{{ selectedRepo.language || 'Code' }}</span><span>★ {{ selectedRepo.stargazers_count }}</span><span>⑂ {{ selectedRepo.forks_count }}</span></div><a class="button button-dark" :href="selectedRepo.html_url" target="_blank" rel="noreferrer">{{ t.viewRepository }} <span>↗</span></a></template><template v-else><span class="eyebrow">{{ t.openConversation }}</span><h2>{{ t.letsTalk }}.</h2><p class="contact-intro">{{ t.contactIntro }}</p><div class="contact-options"><a href="mailto:resyaanggara98@gmail.com"><span class="contact-icon"><Mail :size="17" :stroke-width="1.8" /></span><span><strong>{{ t.email }}</strong><small>resyaanggara98@gmail.com</small></span><b>↗</b></a><a href="https://wa.me/6282114028613" target="_blank" rel="noreferrer"><span class="contact-icon"><Icon icon="simple-icons:whatsapp" /></span><span><strong>{{ t.whatsapp }}</strong><small>{{ t.chatWhatsapp }}</small></span><b>↗</b></a><a href="https://www.instagram.com/ayser_nii/" target="_blank" rel="noreferrer"><span class="contact-icon"><Icon icon="simple-icons:instagram" /></span><span><strong>{{ t.instagram }}</strong><small>@ayser_nii</small></span><b>↗</b></a></div></template></div></div></Transition>
  </div>
</template>

<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;1,600&display=swap');
